{
  "name": "product-bundles",
  "database": {
    "tables": [
      {
        "name": "bundle_definitions",
        "purpose": "Master record for each merchant-created bundle, its configuration, and its current health status.",
        "columns": [
          { "name": "id",                               "sqlType": "UUID",        "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()",          "purpose": "internal id" },
          { "name": "title",                            "sqlType": "TEXT",        "constraints": "NOT NULL",                                        "purpose": null },
          { "name": "bundle_type",                      "sqlType": "TEXT",        "constraints": "NOT NULL",                                        "purpose": "fixed or flexible", "enum": ["fixed", "flexible"] },
          { "name": "flexible_pick_count",              "sqlType": "INTEGER",     "constraints": "NULL",                                            "purpose": "number of items the customer must pick for flexible bundles" },
          { "name": "discount_kind",                    "sqlType": "TEXT",        "constraints": "NOT NULL",                                        "purpose": "percentage, flat-amount, or buy-x-get-y", "enum": ["percentage", "flat-amount", "buy-x-get-y"] },
          { "name": "enabled",                          "sqlType": "BOOLEAN",     "constraints": "NOT NULL DEFAULT true",                           "purpose": null },
          { "name": "health_status",                    "sqlType": "TEXT",        "constraints": "NOT NULL DEFAULT 'ok'",                           "purpose": "ok or degraded — set to degraded when a component product/variant is deleted or disabled", "enum": ["ok", "degraded"] },
          { "name": "shopify_bundle_product_external_id","sqlType": "BIGINT",     "constraints": "NULL",                                            "purpose": "the Shopify product bundle resource created for this definition" },
          { "name": "purchase_count",                   "sqlType": "INTEGER",     "constraints": "NOT NULL DEFAULT 0",                              "purpose": "pre-aggregated count of confirmed paid orders attributing this bundle" },
          { "name": "created_at",                       "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",                          "purpose": null },
          { "name": "updated_at",                       "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",                          "purpose": null }
        ],
        "indexes": [
          ["enabled", "health_status", "created_at"],
          ["shopify_bundle_product_external_id"]
        ],
        "foreignKeys": []
      },
      {
        "name": "bundle_components",
        "purpose": "The individual product or variant slots that make up a bundle definition.",
        "columns": [
          { "name": "id",                    "sqlType": "UUID",    "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_id",             "sqlType": "UUID",    "constraints": "NOT NULL REFERENCES bundle_definitions(id) ON DELETE CASCADE", "purpose": "parent bundle definition" },
          { "name": "product_external_id",   "sqlType": "BIGINT",  "constraints": "NOT NULL",                             "purpose": "the source product for this slot" },
          { "name": "variant_external_id",   "sqlType": "BIGINT",  "constraints": "NULL",                                 "purpose": "specific variant when the merchant pins to a variant; null means any variant of the product" },
          { "name": "quantity",              "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 1",                   "purpose": null },
          { "name": "position",              "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0",                   "purpose": "display order within the bundle" }
        ],
        "indexes": [
          ["bundle_id", "position"],
          ["product_external_id"],
          ["variant_external_id"]
        ],
        "foreignKeys": []
      },
      {
        "name": "bundle_discount_tiers",
        "purpose": "Configurable discount tiers per bundle, each mapped to a Shopify discount code.",
        "columns": [
          { "name": "id",                   "sqlType": "UUID",        "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "bundle_id",            "sqlType": "UUID",        "constraints": "NOT NULL REFERENCES bundle_definitions(id) ON DELETE CASCADE", "purpose": "parent bundle definition" },
          { "name": "min_item_count",       "sqlType": "INTEGER",     "constraints": "NOT NULL",                             "purpose": "minimum number of items in the bundle for this tier to activate" },
          { "name": "discount_value",       "sqlType": "BIGINT",      "constraints": "NULL",                                 "purpose": "fractional rate for percentage-off tiers stored as integer basis points (e.g. 2000 = 20%)" },
          { "name": "discount_amount",      "sqlType": "BIGINT",      "constraints": "NULL",                                 "purpose": "flat currency amount off for flat-amount tiers in minor units" },
          { "name": "free_item_count",      "sqlType": "INTEGER",     "constraints": "NULL",                                 "purpose": "number of items that are free for buy-x-get-y tiers" },
          { "name": "discount_code",        "sqlType": "TEXT",        "constraints": "NOT NULL",                             "purpose": "the unique Shopify discount code string for this tier" },
          { "name": "discount_external_id", "sqlType": "BIGINT",      "constraints": "NOT NULL",                             "purpose": "the Shopify discount node id for this tier's code" },
          { "name": "created_at",           "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",               "purpose": null }
        ],
        "uniqueConstraint": ["bundle_id", "min_item_count"],
        "indexes": [
          ["discount_code"],
          ["bundle_id", "min_item_count"]
        ],
        "foreignKeys": []
      },
      {
        "name": "bundle_purchase_attributions",
        "purpose": "Records each confirmed paid order that used a bundle discount code, linking the order to the exact bundle and tier that triggered.",
        "columns": [
          { "name": "id",               "sqlType": "UUID",        "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "order_external_id","sqlType": "BIGINT",      "constraints": "NOT NULL",                             "purpose": "the paid order that used the bundle discount" },
          { "name": "bundle_id",        "sqlType": "UUID",        "constraints": "NOT NULL REFERENCES bundle_definitions(id)", "purpose": "the bundle definition that was purchased" },
          { "name": "tier_id",          "sqlType": "UUID",        "constraints": "NOT NULL REFERENCES bundle_discount_tiers(id)", "purpose": "the specific tier that was applied" },
          { "name": "discount_code",    "sqlType": "TEXT",        "constraints": "NOT NULL",                             "purpose": "the discount code string that was redeemed" },
          { "name": "order_total",      "sqlType": "BIGINT",      "constraints": "NOT NULL",                             "purpose": "order total in minor units" },
          { "name": "currency",         "sqlType": "TEXT",        "constraints": "NOT NULL DEFAULT 'USD'",               "purpose": "currency code for order_total" },
          { "name": "created_at",       "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()",               "purpose": null }
        ],
        "uniqueConstraint": ["order_external_id"],
        "indexes": [
          ["bundle_id"],
          ["tier_id"],
          ["order_external_id"]
        ],
        "foreignKeys": []
      }
    ]
  },
  "shopifyIntegration": {
    "webhookTopics": [
      "orders/paid",
      "products/update",
      "products/delete"
    ],
    "scopes": [
      "read_products",
      "write_products",
      "read_discounts",
      "write_discounts",
      "read_orders"
    ]
  },
  "httpRoutes": {
    "admin": [
      {
        "path": "/admin/bundles",
        "method": "GET",
        "purpose": "Return a paginated list of all bundle definitions with summary fields for the admin dashboard table."
      },
      {
        "path": "/admin/bundles/create",
        "method": "POST",
        "purpose": "Create a new bundle definition including its component items, discount type, and tiers."
      },
      {
        "path": "/admin/bundles/update",
        "method": "PUT",
        "purpose": "Edit any field on an existing bundle definition and re-sync discount codes in Shopify."
      },
      {
        "path": "/admin/bundles/toggle",
        "method": "POST",
        "purpose": "Enable or disable one or more bundles in bulk."
      },
      {
        "path": "/admin/bundles/detail",
        "method": "GET",
        "purpose": "Fetch the full definition of a single bundle for the edit form."
      }
    ],
    "widget": [
      {
        "path": "/widget/bundles",
        "method": "GET",
        "purpose": "Return all enabled bundle definitions that include a given product external id, used by the storefront widget on page load."
      },
      {
        "path": "/widget/bundle/add-to-cart",
        "method": "POST",
        "purpose": "Add all selected bundle items to the Shopify cart and apply the matching tier discount code in one atomic action."
      },
      {
        "path": "/widget/bundle/preview-total",
        "method": "POST",
        "purpose": "Compute and return the live discounted total for a customer's current bundle selection without modifying the cart."
      }
    ]
  }
}
